#include <iostream>
#include <cassert>
#include "vec.hpp"

int main() {
    // Test basic vector creation and access
    qm::Vec a(3, 1.0);
    qm::Vec b(3, 2.0);

    assert(a.size() == 3);
    assert(b.size() == 3);
    assert(a[0] == 1.0);
    assert(b[1] == 2.0);

    // Test addition
    auto c = a + b;
    assert(c.size() == 3);
    assert(c[0] == 3.0);
    assert(c[1] == 3.0);

    // Test subtraction
    auto d = b - a;
    assert(d.size() == 3);
    assert(d[0] == 1.0);
    assert(d[1] == 1.0);

    // Test scalar multiplication
    auto e = a * 2.0;
    assert(e.size() == 3);
    assert(e[0] == 2.0);
    assert(e[1] == 2.0);

    // Test scalar division
    auto f = b / 2.0;
    assert(f.size() == 3);
    assert(f[0] == 1.0);
    assert(f[1] == 1.0);

    // Test unary minus
    auto g = -a;
    assert(g.size() == 3);
    assert(g[0] == -1.0);
    assert(g[1] == -1.0);

    // Test complex expression
    auto h = (a + b) * 2.0 - a;
    assert(h.size() == 3);
    assert(h[0] == 3.0);
    assert(h[1] == 3.0);

    // Test assignment
    qm::Vec result(3);
    result = a + b;
    assert(result[0] == 3.0);
    assert(result[1] == 3.0);

    // Test reduction functions
    assert(qm::sum(a) == 3.0);
    assert(qm::dot(a, b) == 6.0);
    assert(qm::max(a) == 1.0);

    // Test shift
    auto shifted = qm::shift(a, 1);
    assert(shifted.size() == 3);

    // Test aliasing (a = a + b)
    qm::Vec aliased(3, 1.0);
    aliased = aliased + b;
    assert(aliased[0] == 3.0);
    assert(aliased[1] == 3.0);

    std::cout << "All tests passed!" << std::endl;
    return 0;
}

